54	// SFCC site ID (e.g. ZimmermannEUfr → SFCC ZimmermannEU).
55	type SiteConfig = {
56	  id: string;
57	  sfccSiteId?: string;
58	  alias?: string;
59	  l10n: {
60	    defaultLocale: string;
61	    supportedLocales: SiteLocale[];
