94	/**
95	 * Use the AppConfig component to inject extra arguments into the getProps
96	 * methods for all Route Components in the app – typically you'd want to do this
97	 * to inject a connector instance that can be used in all Pages.
98	 *
99	 * You can also use the AppConfig to configure a state-management library such
100	 * as Redux, or Mobx, if you like.
101	 */
102	const AppConfig = ({ children, locals = {} }: AppConfigProps): React.ReactElement => {
103	  const { correlationId } = useCorrelationId();
104	  const headers = {
105	    'correlation-id': correlationId,
106	    sfdc_user_agent: sfdcUserAgent,
107	  };
108	
109	  if (!locals.appConfig) throw new Error('AppConfig: locals.appConfig is required');
110	  const commerceApiConfig = locals.appConfig.commerceAPI;
111	  const locale = locals.locale?.id ?? 'en-US';
112	
113	  const appOrigin = getAppOrigin();
114	  const passwordlessCallbackURI = getPasswordlessCallbackUrl(locals.appConfig?.login?.passwordless?.callbackURI);
115	
116	  const storeLocatorConfig = {
117	    radius: STORE_LOCATOR_RADIUS,
118	    radiusUnit: STORE_LOCATOR_RADIUS_UNIT,
119	    defaultCountry: STORE_LOCATOR_DEFAULT_COUNTRY,
120	    defaultCountryCode: STORE_LOCATOR_DEFAULT_COUNTRY_CODE,
121	    defaultPostalCode: STORE_LOCATOR_DEFAULT_POSTAL_CODE,
122	    defaultPageSize: STORE_LOCATOR_DEFAULT_PAGE_SIZE,
123	    supportedCountries: STORE_LOCATOR_SUPPORTED_COUNTRIES,
124	  };
125	
126	  // Set absolute uris for CommerceApiProvider proxies and callbacks
127	  const redirectURI = `${appOrigin}${getEnvBasePath()}/callback`;
128	  const proxy = `${appOrigin}${getEnvBasePath()}${commerceApiConfig.proxyPath}`;
129	  const slasPrivateClientProxyEndpoint = `${appOrigin}${getEnvBasePath()}${slasPrivateProxyPath}`;
130	
131	  return (
132	    <CommerceApiProvider
133	      shortCode={commerceApiConfig.parameters.shortCode}
134	      clientId={commerceApiConfig.parameters.clientId}
135	      organizationId={commerceApiConfig.parameters.organizationId}
136	      siteId={locals.site?.sfccSiteId ?? locals.site?.id ?? ''}
137	      locale={locale}
138	      currency={locals.locale?.preferredCurrency ?? ''}
139	      redirectURI={redirectURI}
140	      proxy={proxy}
141	      headers={headers}
142	      defaultDnt={DEFAULT_DNT_STATE}
143	      logger={createLogger({ packageName: 'commerce-sdk-react' })}
144	      passwordlessLoginCallbackURI={passwordlessCallbackURI}
145	      // Set 'enablePWAKitPrivateClient' to true to use SLAS private client login flows.
146	      // Make sure to also enable useSLASPrivateClient in ssr.js when enabling this setting.
147	      enablePWAKitPrivateClient={true}
148	      privateClientProxyEndpoint={slasPrivateClientProxyEndpoint}
149	      // Uncomment 'hybridAuthEnabled' if the current site has Hybrid Auth enabled. Do NOT set this flag for hybrid storefronts using Plugin SLAS.
150	      // hybridAuthEnabled={true}
151	    >
152	      <MultiSiteProvider site={locals.site} locale={locals.locale} buildUrl={locals.buildUrl}>
153	        <StoreLocatorProvider config={storeLocatorConfig}>
154	          <ContentfulLivePreviewProvider locale={locale} enableInspectorMode enableLiveUpdates>
155	            <ChakraProvider theme={theme}>{children}</ChakraProvider>
156	          </ContentfulLivePreviewProvider>
157	        </StoreLocatorProvider>
158	      </MultiSiteProvider>
159	      <ReactQueryDevtools />
160	    </CommerceApiProvider>
161	  );
162	};
