164	AppConfig.restore = (locals: AppLocals = {}): void => {
165	  const path =
166	    typeof window === 'undefined' ? locals.originalUrl ?? '/' : `${window.location.pathname}${window.location.search}`;
167	
168	  // resolveSiteFromUrl only matches a site alias/ID in the URL. When url.site is 'none' the site
169	  // segment is absent, so it always falls back to the defaultSite. In that case, find the real site
170	  // by matching the locale alias from the URL against each site's supportedLocales.
171	  const defaultResolved = resolveSiteFromUrl(path);
172	  const { localeRef } = getParamsFromPath(path);
173	  type SupportedLocale = { id: string; alias?: string };
174	  // sfccSiteId overrides the SFCC Commerce API siteId for PWA sites that don't share their ID
175	  // with their SFCC counterpart (e.g. ZimmermannEUfr → SFCC ZimmermannEU).
176	  type Site = {
177	    id: string;
178	    sfccSiteId?: string;
179	    alias?: string;
180	    l10n: { defaultLocale: string; supportedLocales: SupportedLocale[] };
181	  };
182	  const site: Site = localeRef
183	    ? (getSites() as Site[]).find((s) =>
184	        s.l10n.supportedLocales.some((l) => l.alias === localeRef || l.id === localeRef),
185	      ) ?? defaultResolved
186	    : defaultResolved;
187	
188	  // resolveLocaleFromUrl also calls resolveSiteFromUrl internally, so it would return the wrong
189	  // site too. Resolve the locale directly from the site we already found above.
190	  const locale = (getLocaleByReference(site, localeRef ?? site.l10n.defaultLocale) ??
191	    getLocaleByReference(site, site.l10n.defaultLocale)) as SiteLocale;
192	
193	  const { app: appConfig } = getConfig() as { app: NonNullable<AppLocals['appConfig']> };
194	  const apiConfig = {
195	    ...appConfig.commerceAPI,
196	    einsteinConfig: appConfig.einsteinAPI,
197	  };
198	
199	  apiConfig.parameters.siteId = site.sfccSiteId ?? site.id;
200	
201	  locals.buildUrl = createUrlTemplate(appConfig, site.alias || site.id, locale.alias || locale.id);
202	  locals.site = site;
203	  locals.locale = locale;
204	  locals.appConfig = appConfig;
205	};
