223	  queryClientConfig: {
224	    defaultOptions: {
225	      queries: {
226	        retry: false,
227	        refetchOnWindowFocus: false,
228	        staleTime: 10 * 1000,
229	        ...(isServerSide ? { retryOnMount: false } : {}),
