20	  async goto(path = '') {
21	    const response = await this.page.goto(`${RETAIL_APP_HOME}${path}`);
22	    // 'networkidle' timed out against the real dev environment — this app
23	    // never goes fully network-idle (analytics, consent tooling, etc.), same
24	    // reason Playwright's own docs discourage relying on it. Every other
25	    // Page Object method here already uses the default 'load' state via a
26	    // bare waitForLoadState() call; goto() was the only outlier.
27	    await this.page.waitForLoadState();
28	    await this.dismissConsent();
29	    return response;
30	  }
31	
32	  // Didomi's consent dialog is a true aria-modal="true" dialog on first visit
33	  // (no consent cookie yet in a fresh test browser context) — while it's
34	  // open, the rest of the page is inert to the accessibility tree, so every
35	  // getByRole() query against header/nav/content fails until it's dismissed.
36	  // Confirmed against the real dev environment: AGENTS.md > Consent &
37	  // Marketing's "fail closed on consent" behaviour extends to blocking
38	  // interaction with the rest of the page, not just gating third-party
39	  // scripts. Declines rather than accepts — no reason for CI/bot traffic to
40	  // opt into tracking.
41	  //
42	  // Didomi loads its banner asynchronously and its render time varies by
43	  // environment — near-instant against a warmed, minified deployed bundle,
44	  // several seconds against an unminified local dev-server bundle. An
45	  // instant .count() check races this and silently does nothing on a slow
46	  // render, leaving the dialog to block the rest of the test later. Wait
47	  // for it (bounded) instead, and treat a timeout as "no dialog appeared"
48	  // (e.g. consent already recorded) rather than an error.
49	  async dismissConsent() {
50	    const declineButton = this.page.getByRole('button', { name: /decline tracking/i });
51	    try {
52	      await declineButton.waitFor({ state: 'visible', timeout: 10000 });
53	    } catch (error) {
54	      if (error instanceof errors.TimeoutError) return; // No consent dialog appeared — nothing to dismiss.
55	      throw error;
56	    }
57	    // Outside the try/catch: a real click failure must propagate rather than
58	    // be swallowed as "no dialog appeared", which would let goto() continue
59	    // with the modal still blocking the rest of the page.
60	    await declineButton.click();
61	  }
62	
63	  async waitForVisible(locator) {
64	    await expect(locator).toBeVisible();
